package net.civeira.phylax.features.access.oauthclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.features.access.oauthclient.domain.OauthClientSubjectTypeOptions;

class SubjectTypeVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property subject type of oauth client ")
  void test_subject_type_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> SubjectTypeVO.tryFrom("_PUBLIC_"));
    Assertions.assertEquals(OauthClientSubjectTypeOptions.PUBLIC,
        SubjectTypeVO.tryFrom("PUBLIC").getSubjectType());
    Assertions.assertThrows(ConstraintException.class, () -> SubjectTypeVO.tryFrom(null));
    Assertions.assertEquals(OauthClientSubjectTypeOptions.PUBLIC,
        SubjectTypeVO.from(OauthClientSubjectTypeOptions.PUBLIC).getSubjectType());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> SubjectTypeVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + OauthClientSubjectTypeOptions.PUBLIC + "]",
        SubjectTypeVO.from(OauthClientSubjectTypeOptions.PUBLIC).toString());
  }
}
